    complianceFrameworks = pgTable2("compliance_frameworks", {
      id: uuid("id").primaryKey().defaultRandom(),
      organizationId: uuid("organization_id").notNull(),
      name: varchar("name", { length: 255 }).notNull(),
      // 'SOX', 'GDPR', 'ISO27001', etc.
      category: varchar("category", { length: 100 }),
      // 'financial', 'security', 'operational'
      version: varchar("version", { length: 50 }),
      requirements: jsonb("requirements"),
      // Detailed compliance requirements
      controls: jsonb("controls"),
      // Control frameworks and procedures
      assessmentCriteria: jsonb("assessment_criteria"),
      reportingSchedule: varchar("reporting_schedule", { length: 100 }),
      responsibleParty: varchar("responsible_party"),
      // user ID
      status: complianceStatusEnum("status").default("under_review"),
      lastAssessment: timestamp2("last_assessment"),
      nextAssessment: timestamp2("next_assessment"),
      riskLevel: riskLevelEnum("risk_level").default("moderate"),
      documentation: jsonb("documentation"),
      // Supporting documents and evidence
      auditTrail: jsonb("audit_trail"),
      // History of changes and assessments
      createdAt: timestamp2("created_at").defaultNow(),
      updatedAt: timestamp2("updated_at").defaultNow()
    });
    complianceReports = pgTable2("compliance_reports", {
      id: uuid("id").primaryKey().defaultRandom(),
      organizationId: uuid("organization_id").notNull(),
      frameworkId: uuid("framework_id").notNull(),
      reportType: varchar("report_type", { length: 100 }),
      // 'quarterly', 'annual', 'exception', 'audit'
      reportingPeriod: varchar("reporting_period", { length: 100 }),
      overallStatus: complianceStatusEnum("overall_status").default("compliant"),
      complianceScore: decimal("compliance_score", { precision: 3, scale: 2 }),
      // 0.00-1.00
      controlsAssessed: integer2("controls_assessed"),
      controlsPassed: integer2("controls_passed"),
      controlsFailed: integer2("controls_failed"),
      exceptions: jsonb("exceptions"),
      // Controls with exceptions
      remediation: jsonb("remediation"),
      // Action plans for non-compliance
      evidence: jsonb("evidence"),
      // Supporting evidence and documentation
      recommendations: jsonb("recommendations"),
      // Improvement recommendations
      riskAssessment: jsonb("risk_assessment"),
      executiveSummary: text2("executive_summary"),
      detailedFindings: jsonb("detailed_findings"),
      generatedBy: varchar("generated_by"),
      // user ID or 'system'
      reviewedBy: varchar("reviewed_by"),
      // user ID
      approvedBy: varchar("approved_by"),
      // user ID
      submittedAt: timestamp2("submitted_at"),
      dueDate: timestamp2("due_date"),
      createdAt: timestamp2("created_at").defaultNow()
    });
    backgroundJobs = pgTable2("background_jobs", {
      id: uuid("id").primaryKey().defaultRandom(),
      queueName: varchar("queue_name", { length: 100 }).notNull(),
      // 'analysis', 'reports', 'alerts'
      jobType: varchar("job_type", { length: 100 }).notNull(),
      // Specific job type within queue
      data: jsonb("data").notNull(),
      // Job payload
      priority: integer2("priority").default(0),
      // Higher numbers = higher priority
      status: jobStatusEnum("status").default("pending"),
      maxRetries: integer2("max_retries").default(3),
      attempts: integer2("attempts").default(0),
      error: text2("error"),
      // Last error message
      result: jsonb("result"),
      // Job result data
      runAt: timestamp2("run_at").defaultNow(),
      // When job should run
      startedAt: timestamp2("started_at"),
      // When processing started
      completedAt: timestamp2("completed_at"),
      // When job completed
      failedAt: timestamp2("failed_at"),
      // When job failed permanently
      createdAt: timestamp2("created_at").defaultNow(),
      updatedAt: timestamp2("updated_at").defaultNow()
    }, (table) => [
      index("idx_background_jobs_queue_status").on(table.queueName, table.status),
      index("idx_background_jobs_run_at").on(table.runAt),
      index("idx_background_jobs_priority").on(table.priority)
    ]);
    decisionConfidence = pgTable2("decision_confidence", {
      id: uuid("id").primaryKey().defaultRandom(),
      scenarioId: uuid("scenario_id").references(() => strategicScenarios.id).notNull(),
      organizationId: uuid("organization_id").references(() => organizations.id).notNull(),
      userId: varchar("user_id").references(() => users.id).notNull(),
      // Executive making decision
      overallConfidence: integer2("overall_confidence").notNull(),
      // 0-100 overall confidence score
      dataCompleteness: integer2("data_completeness").notNull(),
      // 0-100 percentage of required data available
      stakeholderAlignment: integer2("stakeholder_alignment").notNull(),
      // 0-100 percentage of key stakeholders aligned
      historicalPrecedent: integer2("historical_precedent"),
      // Number of similar successful executions
      riskCoverage: integer2("risk_coverage").notNull(),
      // 0-100 percentage of identified risks mitigated
      confidenceFactors: jsonb("confidence_factors").notNull(),
      // Detailed breakdown of confidence components
      missingElements: jsonb("missing_elements"),
      // Array of gaps that reduce confidence
      recommendations: jsonb("recommendations"),
      // AI suggestions to improve confidence before activation
      calculatedAt: timestamp2("calculated_at").defaultNow().notNull(),
      createdAt: timestamp2("created_at").defaultNow()
    });
    stakeholderAlignment = pgTable2("stakeholder_alignment", {
      id: uuid("id").primaryKey().defaultRandom(),
      scenarioId: uuid("scenario_id").references(() => strategicScenarios.id).notNull(),
      executionId: uuid("execution_id"),
      // Link to specific playbook execution instance
      organizationId: uuid("organization_id").references(() => organizations.id).notNull(),
      stakeholderId: varchar("stakeholder_id").references(() => users.id).notNull(),
      stakeholderRole: varchar("stakeholder_role", { length: 100 }).notNull(),
      // 'Legal', 'Finance', 'Communications', etc.
      department: varchar("department", { length: 100 }),
      hasAcknowledged: boolean("has_acknowledged").default(false),
      acknowledgedAt: timestamp2("acknowledged_at"),
      assignedTasks: jsonb("assigned_tasks"),
      // Array of task IDs assigned to this stakeholder
      completedTasks: jsonb("completed_tasks"),
      // Array of completed task IDs
      taskCompletionRate: decimal("task_completion_rate", { precision: 3, scale: 2 }),
      // 0.00-1.00
      responseTime: integer2("response_time"),
      // Minutes from notification to acknowledgment
      blockers: jsonb("blockers"),
      // Array of issues preventing task completion
      status: varchar("status", { length: 50 }).default("pending"),
      // 'pending', 'acknowledged', 'in_progress', 'completed'
      notifiedAt: timestamp2("notified_at").defaultNow(),
      updatedAt: timestamp2("updated_at").defaultNow(),
      createdAt: timestamp2("created_at").defaultNow()
    });
    executionValidationReports = pgTable2("execution_validation_reports", {
      id: uuid("id").primaryKey().defaultRandom(),
      scenarioId: uuid("scenario_id").references(() => strategicScenarios.id).notNull(),
      executionId: uuid("execution_id").notNull(),
      // Unique identifier for this specific execution
      organizationId: uuid("organization_id").references(() => organizations.id).notNull(),
      executedBy: varchar("executed_by").references(() => users.id).notNull(),
      executionDate: timestamp2("execution_date").notNull(),
      validationDate: timestamp2("validation_date").defaultNow(),
      // Date report was generated (48hrs after execution)
      // Predicted vs Actual Comparisons
      predictedExecutionTime: integer2("predicted_execution_time"),
      // Minutes
      actualExecutionTime: integer2("actual_execution_time"),
      // Minutes
      timeSavingsRealized: integer2("time_savings_realized"),
      // Minutes saved vs traditional approach
      predictedOutcomes: jsonb("predicted_outcomes").notNull(),
      // Expected results from playbook
      actualOutcomes: jsonb("actual_outcomes").notNull(),
      // Actual results achieved
      outcomeAccuracy: decimal("outcome_accuracy", { precision: 3, scale: 2 }),
      // 0.00-1.00 prediction accuracy
      predictedCost: decimal("predicted_cost", { precision: 12, scale: 2 }),
      actualCost: decimal("actual_cost", { precision: 12, scale: 2 }),
      predictedRisks: jsonb("predicted_risks"),
      // Risks identified before execution
      actualRisks: jsonb("actual_risks"),
      // Risks that materialized during execution
      riskPredictionAccuracy: decimal("risk_prediction_accuracy", { precision: 3, scale: 2 }),
      // Success Metrics
      overallSuccessRating: integer2("overall_success_rating").notNull(),
      // 1-10 rating
      kpiTargetsHit: integer2("kpi_targets_hit"),
      // Number of KPI targets achieved
      kpiTargetsTotal: integer2("kpi_targets_total"),
      // Total number of KPI targets
      // Learnings and Improvements
      whatWorked: jsonb("what_worked"),
      // Array of successful strategies
      whatFailed: jsonb("what_failed"),
      // Array of unsuccessful strategies
      unexpectedChallenges: jsonb("unexpected_challenges"),
      // Surprises encountered
      playbookImprovements: jsonb("playbook_improvements"),
      // Recommended changes to playbook
      institutionalLearnings: text2("institutional_learnings"),
      // Key takeaways for future executions
      // ROI Calculation
      estimatedRoi: decimal("estimated_roi", { precision: 12, scale: 2 }),
      // Return on investment
      timeSavedHours: decimal("time_saved_hours", { precision: 8, scale: 2 }),
      costSavedUsd: decimal("cost_saved_usd", { precision: 12, scale: 2 }),
      // Stakeholder Feedback
      stakeholderFeedback: jsonb("stakeholder_feedback"),
      // Feedback from involved stakeholders
      executiveSummary: text2("executive_summary"),
      // High-level summary for board
      // Confidence for Future Use
      recommendForFutureUse: boolean("recommend_for_future_use").default(true),
      confidenceAdjustment: integer2("confidence_adjustment"),
      // +/- adjustment to future confidence scores
      createdAt: timestamp2("created_at").defaultNow(),
      updatedAt: timestamp2("updated_at").defaultNow()
    });
