async function getSendGridClient2() {
  const hostname = process.env.REPLIT_CONNECTORS_HOSTNAME;
  const xReplitToken = process.env.REPL_IDENTITY ? "repl " + process.env.REPL_IDENTITY : process.env.WEB_REPL_RENEWAL ? "depl " + process.env.WEB_REPL_RENEWAL : null;
  if (!xReplitToken || !hostname) return null;
  try {
    const response = await fetch(
      "https://" + hostname + "/api/v2/connection?include_secrets=true&connector_names=sendgrid",
      { headers: { "Accept": "application/json", "X_REPLIT_TOKEN": xReplitToken } }
    );
    const data = await response.json();
    const connectionSettings = data.items?.[0];
    if (!connectionSettings?.settings?.api_key || !connectionSettings?.settings?.from_email) return null;
    sgMail2.setApiKey(connectionSettings.settings.api_key);
    return { client: sgMail2, fromEmail: connectionSettings.settings.from_email };
  } catch {
    return null;
  }
}
