router4.post("/assess", async (req, res) => {
  try {
    const schema = z4.object({
      companyName: z4.string().optional(),
      domain: z4.enum(["offense", "defense", "special_teams"]).default("defense"),
      answers: z4.record(z4.string())
    });
    const parsed = schema.safeParse(req.body);
    if (!parsed.success) {
      return res.status(400).json({ error: parsed.error.errors[0].message });
    }
    const { companyName, domain, answers } = parsed.data;
    let score = 0;
    const gaps = [];
    const recommendations2 = [];
    if (domain === "offense") {
      if (answers.coordinator && answers.coordinator.length > 3) {
        score += 20;
      } else {
        gaps.push("No designated coordinator for market opportunities");
        recommendations2.push("Designate a strategic opportunity coordinator with cross-functional authority");
      }
      if (answers.speed === "Under 1 week") score += 25;
      else if (answers.speed === "1-4 weeks") score += 20;
      else if (answers.speed === "1-3 months") score += 10;
      else if (answers.speed === "3-6 months") score += 5;
      else {
        gaps.push("Slow opportunity-to-decision cycle");
        recommendations2.push("Pre-authorize go/no-go thresholds to reduce decision latency");
      }
      if (answers.spendingAuthority && answers.spendingAuthority.length > 3 && answers.spendingAuthority.toLowerCase() !== "no one") {
        score += 20;
      } else {
        gaps.push("No pre-authorized market entry spending authority");
        recommendations2.push("Establish pre-authorized spending thresholds: $1M (VP Strategy), $5M (CFO), $10M+ (CEO)");
      }
      if (answers.partners === "Yes fully mapped") score += 20;
      else if (answers.partners === "Partially") {
        score += 10;
        gaps.push("Partner/vendor network only partially pre-qualified");
      } else {
        gaps.push("No pre-qualified partners or channels ready to activate");
        recommendations2.push("Build a pre-qualified partner network for rapid market entry deployment");
      }
      if (answers.playbookLocation === "We don't have one") {
        gaps.push("No documented market entry playbook");
        recommendations2.push("Use ExecuteIQ's 58 Offense playbooks to build your market entry protocols");
      } else if (answers.playbookLocation) {
        score += 15;
        if (["Confluence/SharePoint", "Spreadsheets"].includes(answers.playbookLocation)) {
          gaps.push("Playbook in static documents \u2014 not executable");
          recommendations2.push("Move to executable playbooks with automated triggers");
        }
      }
    } else if (domain === "defense") {
      if (answers.firstNotified && answers.firstNotified.length > 3) {
        score += 20;
      } else {
        gaps.push("No clear incident owner identified");
        recommendations2.push("Designate a primary incident commander with 24/7 availability");
      }
      if (answers.phoneNumber && /\d{7,}/.test(answers.phoneNumber.replace(/\D/g, ""))) {
        score += 15;
      } else {
        gaps.push("Direct contact information not readily available");
        recommendations2.push("Maintain an always-current emergency contact directory");
      }
      if (answers.firstActions && answers.firstActions.length > 10) {
        const actionCount = answers.firstActions.split(/[,;.\n]/).filter((a) => a.trim().length > 2).length;
        score += Math.min(25, actionCount * 8);
        if (actionCount < 3) {
          gaps.push("Insufficient initial response actions defined");
          recommendations2.push("Pre-define at least 5 immediate response actions for each scenario type");
        }
      } else {
        gaps.push("No documented initial response actions");
        recommendations2.push("Create step-by-step action checklists for your top 5 risk scenarios");
      }
      if (answers.spendingAuthority && answers.spendingAuthority.length > 3) {
        if (/\$|budget|authority|approve/i.test(answers.spendingAuthority)) {
          score += 20;
        } else {
          score += 10;
          gaps.push("Spending authority not clearly defined with dollar thresholds");
          recommendations2.push("Set pre-authorized spending limits: $50K (Director), $250K (VP), $1M (C-Suite)");
        }
      } else {
        gaps.push("No pre-authorized spending thresholds");
        recommendations2.push("Establish emergency spending authority without requiring a committee meeting");
      }
      if (answers.playbookLocation === "We don't have one" || answers.playbookLocation === "Don't have one") {
        gaps.push("No documented response playbook exists");
        recommendations2.push("Use ExecuteIQ's 56 Defense playbooks to build your crisis response protocols");
      } else if (answers.playbookLocation) {
        score += 20;
        if (["Confluence/SharePoint", "Spreadsheets", "Confluence", "SharePoint", "Google Doc"].includes(answers.playbookLocation)) {
          gaps.push("Playbook stored in static documents \u2014 not executable");
          recommendations2.push("Move from static documents to executable playbooks");
        }
      }
    } else {
      if (answers.coordinator && answers.coordinator.length > 3) {
        score += 20;
      } else {
        gaps.push("No cross-functional coordination owner");
        recommendations2.push("Designate a Transformation Lead with authority to coordinate across business units");
      }
      if (answers.alignmentSpeed === "Under 1 week") score += 25;
      else if (answers.alignmentSpeed === "1-4 weeks") score += 20;
      else if (answers.alignmentSpeed === "1-3 months") score += 10;
      else if (answers.alignmentSpeed === "3-6 months") score += 5;
      else {
        gaps.push("Stakeholder alignment takes too long");
        recommendations2.push("Implement parallel coordination to reduce alignment time from months to minutes");
      }
      if (answers.raciMatrices === "Yes for all scenarios") score += 20;
      else if (answers.raciMatrices === "Some scenarios") {
        score += 10;
        gaps.push("RACI matrices exist for some but not all scenarios");
      } else {
        gaps.push("No pre-defined RACI matrices for transformation scenarios");
        recommendations2.push("Build RACI matrices for your top transformation scenarios using ExecuteIQ templates");
      }
      if (answers.resourceAuthority && answers.resourceAuthority.length > 3 && !answers.resourceAuthority.toLowerCase().includes("steering committee")) {
        score += 20;
      } else {
        gaps.push("Resource reallocation requires steering committee approval");
        recommendations2.push("Pre-authorize resource reallocation up to 20% at the program lead level");
      }
      if (answers.playbookLocation === "We don't have one") {
        gaps.push("No documented transformation playbook");
        recommendations2.push("Use ExecuteIQ's 52 Special Teams playbooks for transformation initiatives");
      } else if (answers.playbookLocation) {
        score += 15;
        if (["Confluence/SharePoint", "Spreadsheets"].includes(answers.playbookLocation)) {
          gaps.push("Playbook in static documents \u2014 not executable");
          recommendations2.push("Move to executable playbooks with automated coordination");
        }
      }
    }
    score = Math.min(100, Math.max(0, score));
    const domainLabel = domain === "offense" ? "OFFENSE" : domain === "defense" ? "DEFENSE" : "SPECIAL TEAMS";
    const benchmark = score < 30 ? `less prepared than 87% of enterprises in ${domainLabel}` : score < 50 ? `less prepared than 73% of enterprises in ${domainLabel}` : score < 70 ? `on par with 55% of enterprises in ${domainLabel}` : score < 85 ? `better prepared than 62% of enterprises in ${domainLabel}` : `in the top 15% of enterprise ${domainLabel} preparedness`;
    const sessionId = `readiness_${Date.now()}`;
    const [saved] = await db.insert(readinessAssessments).values({
      sessionId,
      companyName: companyName || "Your Company",
      answers,
      score,
      gaps,
      benchmark,
      recommendations: recommendations2
    }).returning();
    res.json({
      id: saved.id,
      domain,
      score,
      gaps,
      benchmark,
      recommendations: recommendations2
    });
  } catch (error) {
    console.error("[Readiness Assessment] Error:", error.message);
    res.status(500).json({ error: "Assessment failed." });
  }
});
router4.post("/what-if", async (req, res) => {
  try {
    const schema = z4.object({
      incidentId: z4.string().uuid().optional(),
      scenario: z4.string().min(10),
      domain: z4.enum(["offense", "defense", "special_teams"]).optional(),
      playbook: z4.any()
    });
    const parsed = schema.safeParse(req.body);
    if (!parsed.success) {
      return res.status(400).json({ error: parsed.error.errors[0].message });
    }
    const { incidentId, scenario, playbook, domain } = parsed.data;
    const domainContext = domain === "offense" ? "This is an OFFENSE scenario (market entry, M&A, product launch). Focus on speed-to-market, competitive advantage, and revenue impact." : domain === "defense" ? "This is a DEFENSE scenario (crisis, cybersecurity, regulatory). Focus on containment speed, compliance deadlines, and damage mitigation." : domain === "special_teams" ? "This is a SPECIAL TEAMS scenario (digital transformation, AI governance, competitive response). Focus on cross-functional coordination, change management, and organizational readiness." : "This is a strategic execution scenario. Determine the domain (offense, defense, or special teams) and analyze accordingly.";
    const prompt = `You are an enterprise strategic execution timing analyst for Fortune 1000 companies. ${domainContext}

Given a playbook that coordinates in ~12 minutes, analyze how a proposed modification would impact coordination time and strategic outcomes.

Return ONLY raw JSON (no markdown):
{
  "original_time": "12 minutes",
  "modified_time": "XX minutes",
  "impact": "+XX min delay (or 'No significant impact' or '-X min improvement')",
  "recommendation": "Recommended / Not recommended / Conditionally recommended \u2014 with a one-sentence explanation",
  "risk_assessment": "Brief assessment of risk tradeoffs",
  "domain": "${domain || "auto-detect"}"
}

Current playbook: ${JSON.stringify(playbook?.name || "Strategic Response Playbook")} with ${playbook?.tasks?.length || 8} tasks and ${playbook?.stakeholders?.length || 6} stakeholders.

Proposed modification: "${scenario}"`;
    let result;
    const aiResponse = await openAIService.analyzeText(prompt);
    try {
      const cleaned = aiResponse.replace(/```json\n?/g, "").replace(/```\n?/g, "").trim();
      result = JSON.parse(cleaned);
    } catch {
      result = {
        original_time: "12 minutes",
        modified_time: "35 minutes",
        impact: "+23 min delay",
        recommendation: "Not recommended. Adds significant delay with minimal risk reduction.",
        risk_assessment: "The proposed change introduces additional coordination overhead without proportional risk mitigation.",
        domain: domain || "strategic"
      };
    }
    if (incidentId) {
      await db.insert(whatIfRuns).values({
        incidentAnalysisId: incidentId,
        scenario,
        originalTime: result.original_time,
        modifiedTime: result.modified_time,
        impact: result.impact,
        recommendation: result.recommendation
      });
    }
    res.json(result);
  } catch (error) {
    console.error("[What-If Analysis] Error:", error.message);
    res.status(500).json({ error: "What-if analysis failed." });
  }
});
