// server/routes/activation-routes.ts
function registerActivationRoutes(app2) {
  app2.get("/api/activation/integrations-status", async (req, res) => {
    try {
      const organizationId = req.query.organizationId;
      if (!organizationId) {
        return res.json({ jira: { connected: false }, slack: { connected: false } });
      }
      const status = await liveIntegrationDispatcher.getIntegrationStatus(organizationId);
      res.json(status);
    } catch (error) {
      res.json({ jira: { connected: false }, slack: { connected: false } });
    }
  });
  app2.post("/api/activation/dispatch-live", async (req, res) => {
    try {
      const { organizationId, playbookName, tasks: tasks4, stakeholders } = req.body;
      if (!organizationId || !playbookName) {
        return res.status(400).json({ success: false, message: "organizationId and playbookName required" });
      }
      const result = await liveIntegrationDispatcher.dispatchActivation(
        organizationId,
        playbookName,
        tasks4 || [],
        stakeholders || []
      );
      res.json({ success: true, ...result });
    } catch (error) {
      console.error("Live dispatch error:", error);
      res.status(500).json({ success: false, message: "Dispatch failed" });
    }
  });
  app2.get("/api/activation/playbooks", async (req, res) => {
    try {
      const playbooks2 = liveActivationService.getAvailablePlaybooks();
      res.json({ success: true, playbooks: playbooks2 });
    } catch (error) {
      console.error("Error fetching available playbooks:", error);
      res.status(500).json({
        success: false,
        message: "Failed to fetch available playbooks"
      });
    }
  });
  app2.post("/api/activation/activate", async (req, res) => {
    try {
      const { playbookKey } = req.body;
      if (!playbookKey || typeof playbookKey !== "string") {
        return res.status(400).json({
          success: false,
          message: "playbookKey is required and must be a string"
        });
      }
      const activationState = await liveActivationService.activatePlaybook(playbookKey);
      const activationId = activationState.id;
      const emitCallback = (event, data) => {
        const io = wsService.getIO();
        if (io) {
          io.to(`activation-${activationId}`).emit(event, data);
        } else {
          console.log(`[${activationId}] ${event}:`, data);
        }
      };
      liveActivationService.startSimulation(activationId, emitCallback);
      res.status(201).json({
        success: true,
        activation: activationState
      });
    } catch (error) {
      console.error("Error activating playbook:", error);
      const errorMessage = error instanceof Error ? error.message : "Unknown error";
      res.status(500).json({
        success: false,
        message: "Failed to activate playbook",
        error: errorMessage
      });
    }
  });
  app2.get("/api/activation/:id", async (req, res) => {
    try {
      const { id } = req.params;
      if (!id) {
        return res.status(400).json({
          success: false,
          message: "Activation ID is required"
        });
      }
      const activationState = liveActivationService.getActivationState(id);
      if (!activationState) {
        return res.status(404).json({
          success: false,
          message: "Activation not found"
        });
      }
      res.json({
        success: true,
        activation: activationState
      });
    } catch (error) {
      console.error("Error fetching activation state:", error);
      res.status(500).json({
        success: false,
        message: "Failed to fetch activation state"
      });
    }
  });
  app2.post("/api/activation/:id/cancel", async (req, res) => {
    try {
      const { id } = req.params;
      if (!id) {
        return res.status(400).json({
          success: false,
          message: "Activation ID is required"
        });
      }
      liveActivationService.cancelSimulation(id);
      res.json({
        success: true,
        message: `Activation ${id} cancelled`
      });
    } catch (error) {
      console.error("Error cancelling activation:", error);
      res.status(500).json({
        success: false,
        message: "Failed to cancel activation"
      });
    }
  });
}

// server/replitAuth.ts
init_storage();
import * as client from "openid-client";
import { Strategy } from "openid-client/passport";
import passport from "passport";
import session from "express-session";
import memoize from "memoizee";
import connectPg from "connect-pg-simple";
var getOidcConfig = memoize(
  async () => {
    return await client.discovery(
      new URL(process.env.ISSUER_URL ?? "https://replit.com/oidc"),
      process.env.REPL_ID
    );
  },
  { maxAge: 3600 * 1e3 }
);
function getSession() {
  const sessionTtl = 7 * 24 * 60 * 60 * 1e3;
  const pgStore = connectPg(session);
  const sessionStore = new pgStore({
    conString: process.env.DATABASE_URL,
    createTableIfMissing: false,
    ttl: sessionTtl,
    tableName: "sessions"
  });
  return session({
    secret: process.env.SESSION_SECRET,
    store: sessionStore,
    resave: false,
    saveUninitialized: false,
    cookie: {
      httpOnly: true,
      secure: true,
      maxAge: sessionTtl
    }
  });
}
function updateUserSession(user, tokens) {
  user.claims = tokens.claims();
  user.access_token = tokens.access_token;
  user.refresh_token = tokens.refresh_token;
  user.expires_at = user.claims?.exp;
}
async function upsertUser(claims) {
  const user = await storage.upsertUser({
    id: claims["sub"],
    email: claims["email"],
    firstName: claims["first_name"],
    lastName: claims["last_name"],
    profileImageUrl: claims["profile_image_url"]
  });
  const userOrgs = await storage.getUserOrganizations(user.id);
  if (userOrgs.length === 0) {
    const orgName = claims["name"] || (claims["email"] ? claims["email"].split("@")[0] : "My Organization");
    await storage.createOrganization({
      name: orgName,
      description: "My Organization",
      ownerId: user.id,
      onboardingCompleted: false
    });
  }
}
async function setupAuth(app2) {
  app2.set("trust proxy", 1);
  app2.use(getSession());
  app2.use(passport.initialize());
  app2.use(passport.session());
  if (!process.env.REPLIT_DOMAINS) {
    return;
  }
  const config = await getOidcConfig();
  const verify = async (tokens, verified) => {
    const user = {};
    updateUserSession(user, tokens);
    await upsertUser(tokens.claims());
    verified(null, user);
  };
  const registeredDomains = [];
  for (const domain of process.env.REPLIT_DOMAINS.split(",")) {
    const trimmed = domain.trim();
    const strategy = new Strategy(
      {
        name: `replitauth:${trimmed}`,
        config,
        scope: "openid email profile offline_access",
        callbackURL: `https://${trimmed}/api/callback`
      },
      verify
    );
    passport.use(strategy);
    registeredDomains.push(trimmed);
  }
  function resolveStrategy(hostname) {
    if (registeredDomains.includes(hostname)) {
      return `replitauth:${hostname}`;
    }
    const replId = hostname.split(".")[0];
    const match = registeredDomains.find((d) => d.startsWith(replId));
    return `replitauth:${match || registeredDomains[0]}`;
  }
  passport.serializeUser((user, cb) => cb(null, user));
  passport.deserializeUser((user, cb) => cb(null, user));
  app2.get("/api/login", (req, res, next) => {
    if (req.query.returnTo && typeof req.query.returnTo === "string") {
      req.session.returnTo = req.query.returnTo;
    } else if (!req.session.returnTo) {
      req.session.returnTo = "/mission-control";
    }
    passport.authenticate(resolveStrategy(req.hostname), {
      prompt: "login consent"
    })(req, res, next);
  });
  app2.get("/api/callback", (req, res, next) => {
    passport.authenticate(resolveStrategy(req.hostname), {
      successReturnToOrRedirect: "/mission-control",
      failureRedirect: "/api/login"
    })(req, res, next);
  });
  app2.get("/api/logout", (req, res) => {
    req.logout(() => {
      res.redirect(
        client.buildEndSessionUrl(config, {
          client_id: process.env.REPL_ID,
          post_logout_redirect_uri: `${req.protocol}://${req.hostname}`
        }).href
      );
    });
  });
}
var isAuthenticated = async (req, res, next) => {
  if (!req.isAuthenticated()) {
    return res.status(401).json({ message: "Unauthorized" });
  }
  return next();
};

// server/replit_integrations/chat/storage.ts
init_db();
init_schema();
import { eq as eq7, desc as desc4 } from "drizzle-orm";
var chatStorage = {
  async getConversation(id) {
    const [conversation] = await db.select().from(conversations).where(eq7(conversations.id, id));
    return conversation;
  },
  async getAllConversations() {
    return db.select().from(conversations).orderBy(desc4(conversations.createdAt));
  },
  async createConversation(title) {
    const [conversation] = await db.insert(conversations).values({ title }).returning();
    return conversation;
  },
  async deleteConversation(id) {
    await db.delete(messages).where(eq7(messages.conversationId, id));
    await db.delete(conversations).where(eq7(conversations.id, id));
  },
  async getMessagesByConversation(conversationId) {
    return db.select().from(messages).where(eq7(messages.conversationId, conversationId)).orderBy(messages.createdAt);
  },
  async createMessage(conversationId, role, content) {
    const [message] = await db.insert(messages).values({ conversationId, role, content }).returning();
    return message;
  }
};

