function isPublicRoute(path3) {
  const pathWithoutQuery = path3.split("?")[0];
  return PUBLIC_ROUTES.some((publicRoute) => {
    if (publicRoute === pathWithoutQuery) return true;
    const pattern = publicRoute.replace(/:[^/]+/g, "[^/]+");
    const regex = new RegExp(`^${pattern}$`);
    return regex.test(pathWithoutQuery);
  });
}
function conditionalAuth(req, res, next) {
  const path3 = req.originalUrl || req.url;
  if (isPublicRoute(path3)) {
    return next();
  }
  const userId = req.user?.claims?.sub || req.user?.sub || req.user?.id || null;
  if (!userId) {
    return res.status(401).json({
      error: "Authentication required",
      message: "This endpoint requires authentication. Please log in to continue."
    });
  }
  req.userId = userId;
  next();
}

// server/seeds/samplePlaybookData.ts
function deterministicId(seed, index2 = 0) {
  let hash = 0;
  const str = `${seed}-${index2}`;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = (hash << 5) - hash + char;
    hash = hash & hash;
  }
  return Math.abs(hash).toString(36).padStart(8, "0").slice(0, 8);
}
function deterministicSelect(arr, seed, index2 = 0) {
  let hash = 0;
  const str = `${seed}-select-${index2}`;
  for (let i = 0; i < str.length; i++) {
    hash = (hash << 5) - hash + str.charCodeAt(i);
    hash = hash & hash;
  }
  return arr[Math.abs(hash) % arr.length];
}
