function calculateTaskValue(task) {
  let baseValue = 500;
  const priorityMultipliers = {
    "critical": 4,
    "high": 2.5,
    "medium": 1.5,
    "low": 1
  };
  const priorityMultiplier = priorityMultipliers[task.priority] || 1;
  const strategicKeywords = ["strategic", "executive", "crisis", "decision", "revenue", "compliance", "risk"];
  const hasStrategicKeyword = strategicKeywords.some(
    (keyword) => task.description?.toLowerCase().includes(keyword)
  );
  const complexityBonus = hasStrategicKeyword ? 1e3 : 0;
  return Math.floor(baseValue * priorityMultiplier + complexityBonus);
}
